helper.pro.dwarfMiner = {
  setting: {
    cIndex: 0
  },
  state: {
    running: false,
    log: false
  },
  history: [],
  get active() {
    return helper.pro.checkMap(this);
  },
  get aid() {
    var e = ActivityController.getActivityByActivityUIType("ActivityDwarfMiner");
    return e && e.id;
  },
  get data() {
    var e = ActivityController._activityMap[this.aid];
    return e && e.extra && e.extra.map;
  },
  get enabled() {
    var e = ActivityController._activityMap[this.aid];
    return e && e.endtime > ServerTime;
  },
  iname: e => LOCAL.getText(TABLE.getTableDataById(TableName.ITEM, e).name),
  cname(e) {
    var t = TABLE.getTableDataById(TableName.miner_chest_open, e);
    t &&= TABLE.getTableDataById(TableName.REWARD, t.reward);
    t &&= TABLE.getTableDataById(TableName.ITEM, t.item);
    return t && LOCAL.getText(t.name);
  },
  cnum(e) {
    var t = TABLE.getTableDataById(TableName.miner_chest_open, e);
    t &&= TABLE.getTableDataById(TableName.REWARD, t.reward);
    return t && t.num;
  },
  vtime(e) {
    var t = TABLE.getTableDataById(TableName.miner_chest_open, e);
    return t && t.vanish_time;
  },
  async reward() {
    var e = this.data.list.find(e => e.expireTime > 0 && e.expireTime <= ServerTime);
    var t = e && ((await helper.its.asend(RequestId.DWARF_MINER_OPEN_CHEST, {
      activityID: this.aid,
      cIndex: e.cIndex
    })) || (await asleep(600000)));
    if (t && t.chestIndex == this.setting.cIndex) {
      this.setting.cIndex = null;
    }
    if (t && t.reward) {
      this.log(t);
    }
  },
  async unlock() {
    if (this.data.list.length && !this.data.list.find(e => e.expireTime > 0)) {
      var e = this.setting.cIndex;
      e ||= this.data.list.concat().sort((e, t) => this.vtime(e.cId) - this.vtime(t.cId))[0].cIndex;
      if (e = e && ((await helper.its.asend(RequestId.DWARF_MINER_UNLOCK_CHEST, {
        activityID: this.aid,
        cIndex: e
      })) || (await asleep(600000)))) {
        this.render();
      }
    }
  },
  async dig() {
    for (var e = Number(GameTools.getDataConfigData(15039)); this.enabled && this.data.digCount < e && this.data.list.length < 4;) {
      var t = (await helper.its.asend(RequestId.DWARF_MINER_DIG, {
        activityID: this.aid
      })) || (await asleep(600000));
      if (t && t.reward) {
        this.log(t);
      }
      await asleep(200);
    }
  },
  log(e) {
    var t = {
      id: e.reward.items[0].itemId,
      count: e.reward.items[0].itemCount
    };
    this.history.splice(0, this.history.length - 19);
    this.history.push({
      time: ServerTime,
      item: {
        dig: e.digCount,
        reward: t
      }
    });
    this.history.changed = true;
    this.render();
  },
  async execute() {
    if (this.data) {
      await this.reward();
      await this.dig();
      await this.unlock();
      if (this.history.changed) {
        this.history.changed = false;
        this.save();
      }
    }
  },
  async schedule() {
    if (!this.busy) {
      try {
        this.busy = 1;
        if (this.active) {
          await this.execute();
        }
      } finally {
        this.busy = 0;
      }
    }
  },
  start() {
    this.timer ||= setInterval(this.schedule.bind(this), 2000);
  },
  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = 0;
    }
  },
  save() {
    helper.settings.set("dwarf-miner", {
      setting: this.setting,
      state: this.state,
      history: this.history
    });
  },
  load() {
    var e = helper.settings.get("dwarf-miner");
    if (e) {
      this.setting = e.setting;
      this.state = e.state;
      this.history = e.history;
    }
  },
  init() {
    this.load();
    if (this.active && this.state.running) {
      this.start();
    }
  },
  free() {
    this.stop();
  },
  startup() {
    if (!this.state.running) {
      this.state.running = true;
      this.start();
      this.save();
      this.render();
    }
  },
  suspend() {
    if (this.state.running) {
      this.state.running = false;
      this.stop();
      this.save();
      this.render();
    }
  },
  fightmodeoff() {
    if (this.state.log) {
      this.startup();
    }
  },
  fightmodeon() {
    var p = this.state.running;
    if (p) {
      this.suspend();
    }
    if (this.state.log !== p) {
      this.state.log = p;
      this.save();
    }
  },
  apply(e) {
    this.setting.cIndex = Number(e);
    this.save();
    this.render();
  },
  render() {
    function e(e) {
      var t;
      var i;
      t = e.time;
      (i = new Date()).setTime(t * 1000);
      var a = i.getMonth() + 1 + "-" + i.getDate() + " " + i.getHours() + ":" + i.getMinutes().toString().padStart(2, "0") + ":" + i.getSeconds().toString().padStart(2, "0");
      if (e.item.reward) {
        a += "  奖励:" + this.iname(e.item.reward.id) + ", 数量:" + e.item.reward.count;
      }
      if (e.item.dig) {
        a += "  第" + e.item.dig + "次挖矿";
      }
      return a;
    }
    var t = helper.dialog.iframe;
    if (t && t.name == "dwarf-miner") {
      var i = [];
      var a = [];
      if (this.data) {
        this.data.list.forEach(e => i.push({
          cIndex: e.cIndex,
          cname: this.cname(e.cId),
          vtime: this.vtime(e.cId),
          expire: e.expireTime
        }));
      }
      for (var r = this.history.length - 1; r >= 0; --r) {
        a.push(e.call(this, this.history[r]));
      }
      t.contentWindow.render(this.setting, i, a, this.state);
    }
  },
  open() {
    helper.dialog.open({
      name: "dwarf-miner",
      html: this.html,
      width: 500,
      onopen: () => this.render()
    });
  }
};
