helper.pro.relicResource = {
  engine: [],
  resources: [],
  refreshCDTime: 0,
  get active() {
    return helper.pro.checkMap(this);
  },
  async execute(Q) {
    var s = Q.length;
    var M = [];
    for (var V = 0; V < 18; V++) {
      M.push(Q[V % s].asend(RequestId.GET_WORLD_INFO, {
        x: 308 + V % 6 * 40,
        y: 248 + parseInt(V / 6) * 60,
        k: UserData.ServerId,
        rid: 0,
        width: 60,
        height: 90,
        marchInfo: true,
        viewLevel: 1
      }));
      M.push(Q[V % s].asend(RequestId.GET_WORLD_INFO, {
        x: 308 + V % 6 * 40,
        y: 588 + parseInt(V / 6) * 60,
        k: UserData.ServerId,
        rid: 0,
        width: 60,
        height: 90,
        marchInfo: true,
        viewLevel: 1
      }));
    }
    M = await Promise.all(M);
    this.resources = [];
    M.forEach(N => N && N.pointList && N.pointList.forEach(I => I.r && I.pointType == 38 && !this.resources.find(h => h.x == I.x && h.y == I.y) && this.resources.push(I)));
    M.forEach(N => N && N.marchList && N.marchList.forEach(I => {
      var h = I.marchType == 3 && this.resources.find(p => p.x == I.target.tx && p.y == I.target.ty);
      if (h) {
        h.gatherTime = I.gatherStartTime;
      }
    }));
    this.resources.sort((N, I) => Math.abs(N.r.expireTime - I.r.expireTime) > 5 ? I.r.expireTime - N.r.expireTime : N.r.itemId != I.r.itemId ? N.r.itemId - I.r.itemId : N.r.ownerId != I.r.ownerId ? N.r.ownerId - I.r.ownerId : helper.tools.distance(N) - helper.tools.distance(I));
    this.resources.forEach(N => {
      var I = TABLE.getTableDataById(TableName.RESOURCE, N.r.itemId.toString());
      N.text = I && LOCAL.getText(I.name.toString());
    });
    this.render();
  },
  async refresh() {
    if (this.refreshCDTime < Date.now()) {
      var Q = await helper.pro.roleEngine.allocate(UserData.ServerId);
      this.refreshCDTime = Date.now() + (Q.length ? Math.floor(20000 / Q.length) : (Q = [NET], 180000));
      await this.execute(Q);
    } else {
      const remainingSec = Math.ceil((this.refreshCDTime - Date.now()) / 1000);
      UIManager.ShowTips(`CD时间还有${remainingSec}秒`);
    }
  },
  render() {
    var Q = helper.dialog.iframe;
    if (Q && Q.name == "relic-resource") {
      Q.contentWindow.render(this.resources, this.refreshCDTime);
    }
  },
  goto(A) {
    var N = __require("NWorldMapData").default.instance.serverData.currentServerId;
    var z = A.innerText.split(",");
    if (z.length == 2) {
      helper.tools.gotoWorldAndClick({
        x: z[0],
        y: z[1],
        k: N,
        subMap: 0
      });
      helper.dialog.close();
    }
  },
  open() {
    helper.dialog.open({
      name: "relic-resource",
      html: this.html,
      width: 480,
      onopen: () => helper.pro.roleEngine.prepare().then(() => this.refresh()),
      onclose: () => helper.pro.roleEngine.dispose()
    });
  }
};
