helper.pro.misc.recruit = {
  setting: {
    count: {
      1: 5,
      2: 1,
      4: 5,
      5: 0,
      6: 0,
      7: 0
    },
    weeks: {
      0: 2,
      1: 15,
      2: 15,
      3: 30,
      4: 2,
      5: 2,
      6: 2
    }
  },
  state: {
    date: 0,
    counter: {
      1: 0,
      2: 0,
      4: 0,
      5: 0,
      6: 0,
      7: 0
    }
  },
  get active() {
    return helper.pro.miscController.check(this);
  },
  get canFreeRecruit() {
    var e = HeroController.getInstance();
    return e.hero2FreeEndTime < ServerTime || e.hero1FreeTodayNum > 0 || e.SkillRecruitLeastTimes < 5;
  },
  async recurit(e, t, i) {
    var a = __require("MvcMsgs");
    var r = UserData.getHeroPickConfig(e);
    if (await helper.its.asend(RequestId.HERO_RECRUIT, {
      extractId: r,
      num: t,
      useDiamond: false,
      isFree: i,
      useHaveNum: false
    })) {
      a.send(a.Names.MVC_HERO_REFRESH, {});
      EVENT.emit(EventId.HeroSkillItemUpdate);
      EVENT.emit(EventId.HeroRecruit);
      this.state.counter[e] += t;
      this.save();
      this.render();
      await asleep(1000);
    }
  },
  async freeRecruit() {
    var e = HeroController.getInstance();
    var t = 1;
    if (e.hero2FreeEndTime < ServerTime && t > 0) {
      await this.recurit(2, t, true);
    }
    t = (t = e.hero1FreeTodayNum) > 0 ? t == 5 && UserData.VipLevel >= 6 ? 5 : 1 : 0;
    if (e.hero1FreeEndTime < ServerTime && t > 0) {
      await this.recurit(1, t, true);
    }
    t = (t = 5 - e.SkillRecruitLeastTimes) > 0 ? t == 5 && UserData.VipLevel >= 6 ? 5 : 1 : 0;
    if (e._heroSkillFreeEndTime < ServerTime && t > 0) {
      await this.recurit(4, t, true);
    }
  },
  async itemRecruit() {
    for (var e in this.setting.count) {
      var t = HeroController.getInstance().getHeroGechaNumMax(e);
      var i = HeroController.getInstance().getHeroGachaNumToday(e);
      if (t == 0 || !(i >= t)) {
        t = t || Number.MAX_SAFE_INTEGER;
        if (!((a = this.setting.count[e] - this.state.counter[e]) <= 0)) {
          var a;
          var r = TABLE.getTableDataById(TableName.EXTRACT, e);
          var n = Math.min(UserData.getItemAmount(r.itemId), t - i);
          if ((a = (a = Math.min(n, a)) >= 10 ? 10 : a > 0 ? 1 : 0) > 0) {
            await this.recurit(e, a, false);
          }
        }
      }
    }
  },
  async execute() {
    if (this.canFreeRecruit) {
      await this.freeRecruit();
    } else {
      await this.itemRecruit();
    }
  },
  async schedule() {
    await asleep(Math.floor(Math.random() * 10000));
    if (!this.busy) {
      try {
        this.busy = 1;
        if (this.active) {
          await this.execute();
        }
      } finally {
        this.busy = 0;
      }
    }
  },
  start() {
    this.timer ||= setInterval(this.schedule.bind(this), 300000);
  },
  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = 0;
    }
  },
  save() {
    helper.settings.set("hero-recruit", {
      setting: this.setting,
      state: this.state
    });
  },
  load() {
    var e = helper.settings.get("hero-recruit");
    if (e) {
      this.setting = e.setting;
      this.state = e.state;
    }
    if (this.setting.weeks == null) {
      this.setting.weeks = {
        0: 2,
        1: 15,
        2: 15,
        3: 30,
        4: 2,
        5: 2,
        6: 2
      };
    }
    if (this.state.counter[0] != null) {
      delete this.state.counter[0];
      delete this.state.counter[3];
      this.save();
    }
  },
  init() {
    this.load();
  },
  free() {
    this.stop();
  },
  dayInit(e) {
    if (this.state.date != e) {
      for (var t in this.state.counter) {
        this.state.counter[t] = 0;
      }
      this.setting.count[2] = this.setting.weeks[new Date(e * 1000).getDay()];
      this.state.date = e;
      this.render();
      this.save();
    }
  },
  apply(e) {
    this.setting = e;
    this.render();
    this.save();
  },
  render() {
    if (helper.pro.miscController.isPopup(this)) {
      helper.dialog.iframe.contentWindow.render_param(this.setting, this.state);
    }
  }
};
