helper.pro.misc.crossPvp.html = String.raw`
<script>
    function render_param(setting) {
        function format(time){
            var hh = Math.floor(time / 3600), mm = Math.floor(time % 3600 / 60), ss = time % 60;
            return String(hh).padStart(2,0) + ':' + String(mm).padStart(2,0) + ':' + String(ss).padStart(2,0);
        }
        stime.value = format(setting.stime);
        etime.value = format(setting.etime);
        interval.children.edit.value = setting.interval + '秒';
        interval.children.edit.setAttribute('value', setting.interval);
        interval.children.list.value = '';
        city_skill.checked = setting.skill.city;
        item_skill.checked = setting.skill.item;
        hero_skill.checked = setting.skill.hero;
    }
    
    function apply_param() {
        var a = stime.value.split(':');
        var s = (Number(a[0]) || 0) * 3600 + (Number(a[1]) || 0) * 60 + Number(a[2]); 
        var a = etime.value.split(':');
        var e = (Number(a[0]) || 0) * 3600 + (Number(a[1]) || 0) * 60 + Number(a[2]); 
        var i = Number(interval.children.edit.getAttribute('value'));
        var o = {city:city_skill.checked, item:item_skill.checked, hero:hero_skill.checked};
        s > 0 && e > s && i > 1 && parent.helper.pro.misc.crossPvp.apply({stime:s, etime:e, interval:i, skill:o});
    }
</script>

<div style="width:410px">
    <span style="display:inline;margin-left:8px">开始时间:</span>
    <input id="stime" style="width:60px" placeholder="hh:mm:ss" onchange="apply_param()"><i></i>
    <span style="display:inline;margin-left:8px">结束时间:</span>
    <input id="etime" style="width:60px" placeholder="hh:mm:ss" onchange="apply_param()"><i></i>
    <span style="display:inline;margin-left:8px">间隔时间:</span>
    <div id="interval" class="combo-box" style="width:60px">
        <select name="list" class="combo-list" onchange="listchange(this)">
            <option value=2>2秒</option>
            <option value=3>3秒</option>
            <option value=4>4秒</option>
            <option value=5>5秒</option>
        </select>
        <input name="edit" class="combo-edit" style="width:40px" onchange="editchange(this)">
    </div>
    <input type="checkbox" id="city_skill" style="margin-left:8px;margin-top:7px" onchange="apply_param()"><label for="city_skill" style="display:inline;width:120px">城市技能</label>
    <input type="checkbox" id="item_skill" style="margin-left:4px;margin-top:7px" onchange="apply_param()"><label for="item_skill" style="display:inline;width:120px">道具增益</label>
    <input type="checkbox" id="hero_skill" style="margin-left:4px;margin-top:7px" onchange="apply_param()"><label for="hero_skill" style="display:inline;width:120px">英雄技能</label>
    <br>
    <span style="color:olive; width:100%; margin-left:8px">请根据网络状况选择适合开始时间、结束时间和间隔时间。</span>
</div>`;
