helper.pro.misc.treasureBoss = {
  setting: {
    preset: -1,
    interval: 120,
    energy: false,
    date: 0,
    count: 20,
    counter: 0,
    quality: 3
  },
  get active() {
    return helper.pro.miscController.check(this);
  },
  async execute() {
    if (this.setting.counter >= this.setting.count) {
      return;
    }
    let Q = this.setting.preset;
    if (!helper.battle.preCheck(Q, 2)) {
      return;
    }
    let e = await helper.its.asend(RequestId.GET_WORLD_INFO, {
      x: UserData.WorldCoord.x,
      y: UserData.WorldCoord.y,
      k: UserData.ServerId,
      rid: 0,
      width: 60,
      height: 90,
      marchInfo: true,
      viewLevel: 1
    });
    let tmwbList = e.pointList.filter(p => p.tmwb);
    if (this.setting.quality != null && this.setting.quality !== 3) {
      tmwbList = tmwbList.filter(p => p.tmwb.quality == this.setting.quality);
    }
    if (!tmwbList.length) {
      return;
    }
    if (!(await helper.tools.checkEnergy(10, this.setting.energy))) {
      return;
    }
    let A = await helper.tools.getTile(tmwbList[0]);
    let K = A && helper.tools.canMarch && (await helper.battle.march(Q, 9999, () => {
      Object.assign(new (__require("WorldBossDetailPanel").default)(), {
        tileInfo: A,
        bossId: A.extData.bossId
      }).onClickAttackBtn();
    }));
    if (K?.["marchInfo"]) {
      this.setting.counter++;
      this.save();
    }
  },
  async schedule() {
    await asleep(Math.floor(Math.random() * 3000));
    if (!this.busy) {
      try {
        this.busy = 1;
        if (this.active) {
          await this.execute();
        }
      } finally {
        this.busy = 0;
      }
    }
  },
  start() {
    let Q = Math.max(this.setting.interval * 1000, 5000);
    if (!this.timer) {
      this.timer = setInterval(this.schedule.bind(this), Q);
    }
  },
  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = 0;
    }
  },
  load() {
    var Q = helper.settings.get("treasure-boss");
    if (Q) {
      this.setting = Q;
      if (Q.counter === undefined) {
        this.setting.date = 0;
        this.setting.counter = 0;
        this.save();
      }
      if (Q.count === undefined) {
        this.setting.count = 20;
        this.save();
      }
      if (Q.quality === undefined) {
        this.setting.quality = 3;
        this.save();
      }
    }
  },
  save() {
    helper.settings.set("treasure-boss", this.setting);
  },
  apply(A) {
    var z = this.setting.interval;
    this.setting.preset = A.preset;
    this.setting.energy = A.energy;
    this.setting.count = A.count;
    this.setting.interval = A.interval > 0 ? A.interval : 120;
    this.setting.quality = A.quality ?? 3;
    if (this.setting.interval != z && this.timer) {
      this.stop();
      this.start();
    }
    this.save();
    this.render();
  },
  init() {
    this.load();
  },
  dayInit(a) {
    if (this.setting.date != a) {
      this.setting.date = a;
      this.setting.counter = 0;
      this.save();
    }
  },
  free() {
    this.stop();
  },
  render() {
    var a = helper.dialog.iframe;
    if (a && a.name == "misc-controller") {
      a.contentWindow.render_param(this.setting);
    }
  }
};
